    basicsMicroAccount: '$100 – $1.000',
    basicsMiniName: 'Мини lot',
    basicsMiniNBadge: 'Средний',
    basicsMiniAccount: '$1.000 – $10.000',
    basicsStdName: 'Стандартный lot',
    basicsStdBadge: 'Продвинутый',
    basicsStdAccount: '$10.000+',
